const doc = new DOMParser().parseFromString(await (await fetch('/data/devices.xml')).text(), 'application/xml');
function xp(expr, ctx = doc) {
  const r = doc.evaluate(expr, ctx, null, XPathResult.ANY_TYPE, null);
  switch (r.resultType) {
    case XPathResult.NUMBER_TYPE: return r.numberValue;
    case XPathResult.STRING_TYPE: return r.stringValue;
    case XPathResult.BOOLEAN_TYPE: return r.booleanValue;
    default: {
      const out = [];
      for (let n = r.iterateNext(); n; n = r.iterateNext()) out.push(n.nodeType === 2 ? `@${n.name}=${n.value}` : n.nodeType === 3 ? n.nodeValue : n.nodeName);
      return out;
    }
  }
}
