const run = (expr, label) => {
  assert(typeof expr === 'string' && expr.trim() !== '', label + ' is empty: write an XPath expression in the string.');
  let r;
  try { r = xml.evaluate(expr, xml, null, XPathResult.ANY_TYPE, null); } catch (e) { assert(false, label + ' is not valid XPath: ' + e.message); }
  if (r.resultType === XPathResult.NUMBER_TYPE) return [String(r.numberValue)];
  if (r.resultType === XPathResult.STRING_TYPE) return [r.stringValue];
  if (r.resultType === XPathResult.BOOLEAN_TYPE) return [String(r.booleanValue)];
  const found = [];
  for (let n = r.iterateNext(); n; n = r.iterateNext()) found.push(n.nodeType === 1 ? n.textContent.trim() : n.nodeValue);
  return found;
};
