const svg = document.querySelector('#chart');
function el(name, attrs, text) {
  const node = document.createElementNS(NS, name);
  for (const [k, v] of Object.entries(attrs)) node.setAttribute(k, v);
  if (text !== undefined) node.textContent = text;
  return node;
}
async function main() {
  const devices = await (await fetch('/api/devices')).json();
  const counts = {};
  for (const d of devices) counts[d.type] = (counts[d.type] ?? 0) + 1;
  Object.keys(counts).sort().forEach((type, i) => {
    const h = counts[type] * 40;
    svg.append(el('rect', { x: i * 50 + 10, y: 120 - h, width: 40, height: h }));
    svg.append(el('text', { x: i * 50 + 30, y: 135, 'text-anchor': 'middle' }, type));
    console.log(type, counts[type]);
  });
}
main();

