assert(out.trim() === 'laptop 1\nprinter 1\nrouter 1\nserver 2\nstorage 1', 'Print "type count" for each type in alphabetical order; got ' + JSON.stringify(out.trim()));
const rects = [...document.querySelectorAll('#chart rect')];
assert(rects.length === 5, 'Draw 5 rect elements (one per type); found ' + rects.length);
assert(rects.every((r) => r instanceof SVGRectElement), 'Create the rects with document.createElementNS("http://www.w3.org/2000/svg", "rect"); createElement makes invisible HTML elements.');
const byX = rects.sort((a, b) => Number(a.getAttribute('x')) - Number(b.getAttribute('x')));
