assert(byX.map((r) => Number(r.getAttribute('y'))).join(',') === '80,80,80,40,80', 'y should be 120 - height, so bars stand on the same baseline.');
const labels = [...document.querySelectorAll('#chart text')].map((t) => t.textContent);
assert(labels.join(',') === 'laptop,printer,router,server,storage' && document.querySelector('#chart text') instanceof SVGTextElement, 'Add one SVG text label per type, in the same order.');
